xt-lg font-bold">Decision</h2><div class="mt-4 space-y-3"><?php foreach ($application['requested_cats'] as $cat): ?><div class="rounded-xl border border-slate-200 p-3"><p class="font-bold"><?= esc($cat['name']) ?></p><form method="post" action="<?= site_url('admin/applications/' . $application['id'] . '/cats/' . $cat['id']) ?>" class="mt-3 flex gap-2"><?= csrf_field() ?><select name="status" class="field text-sm"><?php foreach (['Under Review', 'Approved', 'Rejected'] as $status): ?><option <?= $cat['status'] === $status ? 'selected' : '' ?>><?= $status ?></option><?php endforeach; ?></select><button class="btn btn-primary">Save</button></form></div><?php endforeach; ?></div></div></aside></div><div x-cloak x-show="documentUrl" class="fixed inset-0 z-[200] bg-black/90 p-4" @keydown.escape.window="documentUrl = ''"><button type="button" @click="documentUrl = ''" class="absolute right-5 top-5 rounded-lg bg-white px-4 py-2 text-sm font-bold text-slate-800">Close</button><div class="flex h-full items-center justify-center"><img :src="documentUrl" :alt="documentLabel" class="max-h-full max-w-full object-contain"></div></div></div>
